<script>
(function(){
  var grid   = document.getElementById('grid');
  var notes  = Array.prototype.slice.call(grid.querySelectorAll('.note'));
  var RM     = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var countEl= document.getElementById('bounceCount');
  var bonded = document.getElementById('bonded');
  var bounced= {};

  var tilt  = function(){ return (Math.random()*4.6-2.3).toFixed(2)+'deg'; };
  notes.forEach(function(n){
    n.style.setProperty('--tilt', tilt());
    n.style.setProperty('--lift', (Math.floor(Math.random()*13)-6)+'px');
  });

  /* ---- bounce counter ---- */
  function update(){
    var k = 0; for(var id in bounced) k++;
    countEl.textContent = 'bounced '+k+'/25';
    if(k===25) bonded.classList.add('show');
  }
  function hop(n){
    bounced[n.dataset.id] = true;
    if(!RM){
      var inner = n.querySelector('.note-inner');
      inner.classList.remove('hop');
      void inner.offsetWidth;
      inner.classList.add('hop');
    }
    update();
  }
  notes.forEach(function(n){
    n.addEventListener('click', function(){ hop(n); });
    n.addEventListener('keydown', function(e){
      if(e.key==='Enter'||e.key===' '){ e.preventDefault(); hop(n); }
    });
  });

  /* ---- entrance reveals ---- */
  if(RM || !('IntersectionObserver' in window)){
    notes.forEach(function(n){ n.classList.add('in'); });
  } else {
    var io = new IntersectionObserver(function(entries){
      var seen = entries.filter(function(e){ return e.isIntersecting; });
      seen.forEach(function(e,j){
        e.target.style.setProperty('--d', (j*90)+'ms');
        e.target.classList.add('in');
        io.unobserve(e.target);
      });
    }, {threshold:.12, rootMargin:'0px 0px -4% 0px'});
    notes.forEach(function(n){ io.observe(n); });
  }

  /* ---- shuffle (FLIP) ---- */
  function shuffle(){
    var kids  = Array.prototype.slice.call(grid.children);
    var first = new Map(kids.map(function(k){ return [k, k.getBoundingClientRect()]; }));
    for(var i=kids.length-1;i>0;i--){
      var j = Math.floor(Math.random()*(i+1));
      var t = kids[i]; kids[i]=kids[j]; kids[j]=t;
    }
    kids.forEach(function(k){ grid.appendChild(k); });
    kids.forEach(function(k){
      var f = first.get(k), l = k.getBoundingClientRect();
      var dx = f.left-l.left, dy = f.top-l.top;
      var t  = tilt();
      if(RM){ k.style.setProperty('--tilt', t); return; }
      k.style.transition = 'none';
      k.style.transform  = 'translate('+dx+'px,'+dy+'px) rotate(var(--tilt)) translateY(var(--lift))';
      void k.offsetWidth;
      k.style.transition = 'transform .7s cubic-bezier(.22,.9,.28,1.05)';
      k.style.transform  = 'rotate('+t+') translateY(var(--lift))';
      k.style.setProperty('--tilt', t);
    });
    setTimeout(function(){
      kids.forEach(function(k){ k.style.transition=''; k.style.transform=''; });
    }, 850);
  }
  document.getElementById('shuffleBtn').addEventListener('click', shuffle);

  /* ---- bounce 'em all ---- */
  document.getElementById('bounceBtn').addEventListener('click', function(){
    notes.forEach(function(n,i){ setTimeout(function(){ hop(n); }, i*110); });
  });

  /* ---- watermark parallax ---- */
  if(!RM){
    var a=document.querySelector('.wm-a'), b=document.querySelector('.wm-b'), ticking=false;
    window.addEventListener('scroll', function(){
      if(ticking) return;
      ticking = true;
      requestAnimationFrame(function(){
        var y = window.scrollY;
        a.style.transform = 'translateY('+(y*0.06)+'px)';
        b.style.transform = 'translateY('+(-y*0.05)+'px)';
        ticking = false;
      });
    }, {passive:true});
  }
})();
</script>
</body>
